-- Creates the views only where they don't exist yet: a database that got them some
-- other way (the shared dev DB) keeps its views, and the views that depend on them.--> statement-breakpoint
DO $mig$
BEGIN
  IF to_regclass('master_data.asset_tag_address') IS NULL THEN
    EXECUTE $v$CREATE VIEW "master_data"."asset_tag_address" AS (with "resolved" as (with "own" as (select "region", "asset_id", "work_unit_id", count(*) over (partition by "region", "asset_id") as "placements" from "master_data"."asset_placement" where ("master_data"."asset_placement"."valid_to" is null)), "only" as (select "region", "asset_id", "work_unit_id", count(*) over (partition by "region", "asset_id") as "placements" from "master_data"."asset_placement" where ("master_data"."asset_placement"."valid_to" is null)) select "master_data"."asset_tags"."id" as "asset_tag_id", "master_data"."asset_tags"."region", "master_data"."asset_tags"."asset_id", "master_data"."asset"."asset_tag", "master_data"."asset_tags"."tag_name", "master_data"."asset_tags"."kind", "master_data"."asset_tags"."tag_role", "master_data"."asset_tags"."uom_id", "master_data"."asset_tags"."count_basis", "master_data"."asset_tags"."data_source_id", "master_data"."data_source"."protocol", "master_data"."data_source"."node_naming", "master_data"."data_source"."namespace_uri", "master_data"."data_source"."topic_root", "master_data"."asset_tags"."node" as "typed_node", "master_data"."work_unit"."id" as "work_unit_id", "master_data"."work_center"."id" as "work_center_id", "master_data"."area"."id" as "area_id", "master_data"."site"."id" as "site_id", "master_data"."enterprise"."id" as "enterprise_id", case when "master_data"."enterprise"."id" is not null and "master_data"."asset"."asset_tag" <> '' and "master_data"."asset_tags"."tag_name" <> '' then regexp_replace("master_data"."enterprise"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."site"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."area"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."work_center"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."work_unit"."code", '[^A-Za-z0-9_]', '_', 'g') || '/' || regexp_replace("master_data"."asset"."asset_tag", '[^A-Za-z0-9_]', '_', 'g') || '/' || "master_data"."asset_tags"."tag_name" end as "path", "master_data"."asset_tags"."valid_from", "master_data"."asset_tags"."valid_to" from "master_data"."asset_tags" left join "own" on (("own"."region" = "master_data"."asset_tags"."region") and ("own"."asset_id" = "master_data"."asset_tags"."asset_id") and ("master_data"."asset_tags"."work_unit_id" <> '') and ("own"."work_unit_id" = "master_data"."asset_tags"."work_unit_id")) left join "only" on (("only"."region" = "master_data"."asset_tags"."region") and ("only"."asset_id" = "master_data"."asset_tags"."asset_id") and ("only"."placements" = 1)) left join "master_data"."data_source" on (("master_data"."data_source"."id" = "master_data"."asset_tags"."data_source_id") and ("master_data"."data_source"."region" = "master_data"."asset_tags"."region")) left join "master_data"."asset" on (("master_data"."asset"."id" = "master_data"."asset_tags"."asset_id") and ("master_data"."asset"."region" = "master_data"."asset_tags"."region")) left join "master_data"."work_unit" on (("master_data"."work_unit"."id" = coalesce("own"."work_unit_id", "only"."work_unit_id")) and ("master_data"."work_unit"."region" = "master_data"."asset_tags"."region")) left join "master_data"."work_center" on (("master_data"."work_center"."id" = "master_data"."work_unit"."work_center_id") and ("master_data"."work_center"."region" = "master_data"."asset_tags"."region")) left join "master_data"."area" on (("master_data"."area"."id" = "master_data"."work_center"."area_id") and ("master_data"."area"."region" = "master_data"."asset_tags"."region")) left join "master_data"."site" on (("master_data"."site"."id" = "master_data"."area"."site_id") and ("master_data"."site"."region" = "master_data"."asset_tags"."region")) left join "master_data"."enterprise" on (("master_data"."enterprise"."id" = "master_data"."site"."enterprise_id") and ("master_data"."enterprise"."region" = "master_data"."asset_tags"."region"))) select "asset_tag_id", "region", "asset_id", "asset_tag", "tag_name", "kind", "tag_role", "uom_id", "count_basis", "data_source_id", "protocol", "node_naming", "work_unit_id", "work_center_id", "area_id", "site_id", "enterprise_id", case
        when "node_naming" = 'manual' then nullif("resolved"."typed_node", '')
        when "node_naming" = 'generated' and "protocol" = 'opcua' and "resolved"."path" is not null
          then 'nsu=' || "namespace_uri" || ';s=' || "resolved"."path"
        when "node_naming" = 'generated' and "protocol" = 'mqtt' and "resolved"."path" is not null
          then case when "topic_root" = '' then '' else "topic_root" || '/' end || "resolved"."path"
      end as "node", "valid_from", "valid_to" from "resolved")$v$;
  END IF;
END $mig$;--> statement-breakpoint
DO $mig$
BEGIN
  IF to_regclass('master_data.kpi_binding_node') IS NULL THEN
    EXECUTE $v$CREATE VIEW "master_data"."kpi_binding_node" AS (with "second" as (select "asset_tag_address"."asset_tag_id" as "second_asset_tag_id", "region" as "second_region", "asset_tag_address"."node" as "second_node" from "master_data"."asset_tag_address") select "master_data"."work_unit_kpi_binding"."id" as "binding_id", "master_data"."work_unit_kpi_binding"."region", "master_data"."work_unit_kpi_binding"."work_unit_id", "master_data"."work_unit_kpi_binding"."slot_id", "master_data"."kpi_formula_slot"."domain", "master_data"."kpi_formula_slot"."metric", "master_data"."kpi_formula_slot"."iso_element", "master_data"."work_unit_kpi_binding"."transform", "master_data"."work_unit_kpi_binding"."asset_tag_id", "asset_tag_address"."node", "asset_tag_address"."tag_name", "asset_tag_address"."tag_role", "asset_tag_address"."asset_id", "asset_tag_address"."asset_tag", "master_data"."work_unit_kpi_binding"."second_asset_tag_id", "second"."second_node", "master_data"."work_unit_kpi_binding"."valid_from", "master_data"."work_unit_kpi_binding"."valid_to" from "master_data"."work_unit_kpi_binding" left join "master_data"."kpi_formula_slot" on "master_data"."kpi_formula_slot"."slot_id" = "master_data"."work_unit_kpi_binding"."slot_id" left join "master_data"."asset_tag_address" on (("asset_tag_address"."asset_tag_id" = "master_data"."work_unit_kpi_binding"."asset_tag_id") and ("asset_tag_address"."region" = "master_data"."work_unit_kpi_binding"."region")) left join "second" on (("second"."second_asset_tag_id" = "master_data"."work_unit_kpi_binding"."second_asset_tag_id") and ("second"."second_region" = "master_data"."work_unit_kpi_binding"."region")))$v$;
  END IF;
END $mig$;
